@namespace sv_1c7685b8c59342489ab9790dbbf86fd6.Components.Pages.Settings
@using sv_1c7685b8c59342489ab9790dbbf86fd6.Services

@if (Session is not null)
{
    <div class="modal fade show d-block" tabindex="-1" style="background-color: rgba(0,0,0,0.5);">
        <div class="modal-dialog">
            <div class="modal-content">
                <div class="modal-header">
                    <h5 class="modal-title">Revoke Session</h5>
                    <button type="button" class="btn-close" @onclick="Cancel"></button>
                </div>
                <div class="modal-body">
                    <p>Are you sure you want to revoke this session?</p>
                    <dl class="row mb-0">
                        <dt class="col-sm-4">Device</dt>
                        <dd class="col-sm-8">@Session.Device</dd>
                        <dt class="col-sm-4">Location</dt>
                        <dd class="col-sm-8">@Session.Location</dd>
                        <dt class="col-sm-4">Last Active</dt>
                        <dd class="col-sm-8">@Session.LastActive.ToString("g")</dd>
                    </dl>
                </div>
                <div class="modal-footer">
                    <button type="button" class="btn btn-secondary" @onclick="Cancel">Cancel</button>
                    <button type="button" class="btn btn-danger" @onclick="Confirm">Revoke</button>
                </div>
            </div>
        </div>
    </div>
}

@code {
    [Parameter] public ActiveSession? Session { get; set; }
    [Parameter] public EventCallback OnConfirm { get; set; }
    [Parameter] public EventCallback OnCancel { get; set; }

    private async Task Confirm() => await OnConfirm.InvokeAsync();
    private async Task Cancel() => await OnCancel.InvokeAsync();
}

@namespace sv_1c7685b8c59342489ab9790dbbf86fd6.Components.Pages.Settings
@using sv_1c7685b8c59342489ab9790dbbf86fd6.Services
@inject ISettingsService SettingsService

<div class="settings-section">
    <h3>Security Settings</h3>

    @if (_loading)
    {
        <div class="spinner-border text-primary" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
    }
    else
    {
        <ChangePasswordPanel OnPasswordChanged="ReloadAsync" />

        <div class="card mb-4">
            <div class="card-body">
                <h5 class="card-title">Two-Factor Authentication</h5>
                <div class="d-flex align-items-center gap-3">
                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" id="twoFactor"
                               checked="@_twoFactorEnabled" disabled />
                        <label class="form-check-label" for="twoFactor">
                            @(_twoFactorEnabled ? "Enabled" : "Disabled")
                        </label>
                    </div>
                    <span class="badge @(_twoFactorEnabled ? "bg-success" : "bg-warning text-dark")">
                        @(_twoFactorEnabled ? "Active" : "Inactive")
                    </span>
                </div>
                @if (_lastPasswordChange.HasValue)
                {
                    <p class="text-muted small mt-2 mb-0">
                        Last password change: @_lastPasswordChange.Value.ToString("MMMM dd, yyyy")
                    </p>
                }
            </div>
        </div>

        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Active Sessions</h5>
                <div class="table-responsive">
                    <table class="table table-hover mb-0">
                        <thead>
                            <tr>
                                <th>Device</th>
                                <th>Location</th>
                                <th>Last Active</th>
                                <th></th>
                            </tr>
                        </thead>
