}

.settings-sidebar .nav-link {
    color: #495057;
    border-radius: 0;
    padding: 0.75rem 1.5rem;
    text-align: left;
    width: 100%;
    display: flex;
    align-items: center;
    gap: 0.5rem;
    border: none;
    background: none;
