}

.settings-sidebar .nav-link:hover {
    background-color: #e9ecef;
    color: #212529;
}

.settings-sidebar .nav-link.active {
    background-color: #0d6efd;
    color: #fff;
}

.settings-content {
    flex: 1;
    padding: 2rem;
    overflow-y: auto;
}

.settings-section h3 {
    margin-bottom: 1.5rem;
    padding-bottom: 0.75rem;
    border-bottom: 1px solid #dee2e6;
}

.avatar-preview {
    padding: 1rem;
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    background-color: #f8f9fa;
}

/* Appearance Preview */
.appearance-preview {
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    overflow: hidden;
    min-height: 200px;
    background-color: #ffffff;
    color: #212529;
    transition: all 0.2s ease;
}

.appearance-preview.preview-dark {
    background-color: #1e1e2e;
    color: #e0e0e0;
    border-color: #444;
}

.appearance-preview.preview-compact .preview-content,
.appearance-preview.preview-compact .preview-header,
.appearance-preview.preview-compact .preview-sidebar {
    padding: 0.4rem 0.75rem;
}

.preview-header {
    padding: 0.75rem 1rem;
