toolArgs.file_text:
@page "/settings"
@namespace sv_1c7685b8c59342489ab9790dbbf86fd6.Components.Pages.Settings
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-layout">
    <SettingsSidebar ActiveSection="@_activeSection" OnSectionChanged="section => _activeSection = section" />

    <div class="settings-content">
        @switch (_activeSection)
        {
            case "Profile":
                <ProfileSection />
                break;
            case "Notifications":
                <NotificationsSection />
                break;
            case "Security":
                <SecuritySection />
                break;
            case "Appearance":
                <AppearanceSection />
                break;
        }
    </div>
</div>

@code {
    private string _activeSection = "Profile";
}

.settings-layout {
    display: flex;
    min-height: calc(100vh - 100px);
    gap: 0;
}

.settings-sidebar {
    width: 220px;
    background-color: #f8f9fa;
    border-right: 1px solid #dee2e6;
    padding: 1.5rem 0;
    flex-shrink: 0;
}

.settings-sidebar .nav-link {
    color: #495057;
    border-radius: 0;
    padding: 0.75rem 1.5rem;
    text-align: left;
    width: 100%;
    display: flex;
    align-items: center;
    gap: 0.5rem;
    border: none;
    background: none;
    font-size: 0.95rem;
}

.settings-sidebar .nav-link:hover {
    background-color: #e9ecef;
    color: #212529;
}

.settings-sidebar .nav-link.active {
    background-color: #0d6efd;
    color: #fff;
}

.settings-content {
    flex: 1;
    padding: 2rem;
    overflow-y: auto;
}

.settings-section h3 {
    margin-bottom: 1.5rem;
    padding-bottom: 0.75rem;
    border-bottom: 1px solid #dee2e6;
}

.avatar-preview {
    padding: 1rem;
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    background-color: #f8f9fa;
}

/* Appearance Preview */
.appearance-preview {
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    overflow: hidden;
    min-height: 200px;
    background-color: #ffffff;
    color: #212529;
    transition: all 0.2s ease;
}

.appearance-preview.preview-dark {
    background-color: #1e1e2e;
    color: #e0e0e0;
    border-color: #444;
}

.appearance-preview.preview-compact .preview-content,
.appearance-preview.preview-compact .preview-header,
.appearance-preview.preview-compact .preview-sidebar {
    padding: 0.4rem 0.75rem;
}

.preview-header {
    padding: 0.75rem 1rem;
    font-weight: 600;
    border-bottom: 1px solid #dee2e6;
    background-color: rgba(0, 0, 0, 0.03);
}

.preview-dark .preview-header {
    border-bottom-color: #444;
    background-color: rgba(255, 255, 255, 0.05);
}

.preview-content {
    padding: 1rem;
}

.preview-sidebar {
    padding: 0.75rem 1rem;
    border-top: 1px solid #dee2e6;
    background-color: rgba(0, 0, 0, 0.02);
    font-size: 0.85em;
}

.preview-dark .preview-sidebar {
    border-top-color: #444;
    background-color: rgba(255, 255, 255, 0.03);
}

.preview-btn {
    padding: 0.25rem 0.75rem;
    border-radius: 0.25rem;
    border: 1px solid #0d6efd;
    background-color: #0d6efd;
    color: #fff;
    font-size: inherit;
    cursor: pointer;
}

.preview-dark .preview-btn {
    background-color: #6366f1;
    border-color: #6366f1;
}

